  frame.invalidateToolbarImages();frame.applyAppearance();check(allPixels(images(frame))==overridePixels,"Fresh uncached regeneration matches all cached state pixels exactly");
  const auto skin=output/L"custom.tbi",strip=output/L"custom.bmp";solidImage(strip,32*12,32,24,RGB(231,29,71));atomicText(skin,"v=3\nname=Cache fixture\nlarge=custom.bmp\n",false);settings["ToolbarSkin"]=utf8(skin.wstring());manager.setSettings(settings);const int beforeCustom=decodes;frame.applyAppearance();const auto custom=images(frame);const auto customPixels=allPixels(custom);solidImage(strip,32*12,32,24,RGB(29,71,231));frame.applyAppearance();check(images(frame)!=custom&&allPixels(images(frame))!=customPixels&&decodes==beforeCustom,"Custom skins keep their existing fresh-file behavior instead of entering the built-in cache");settings["ToolbarSkin"]="";manager.setSettings(settings);frame.applyAppearance();check(allPixels(images(frame))==overridePixels&&decodes==beforeCustom,"Returning from an equal-sized custom skin restores built-in pixels without stale active handles");
  const auto beforeFailure=images(frame);const auto savedPixels=allPixels(beforeFailure);int attempts=0;bool fail=true;frame.toolbarSourceObserver=[&](int index){++attempts;if(index==3&&fail){fail=false;throw std::runtime_error("Owned icon load failure");}};frame.invalidateToolbarImages();bool rejected=false;try{frame.applyAppearance();}catch(const std::exception& error){rejected=std::string(error.what())=="Owned icon load failure";}
  check(rejected&&frame.toolbarSources.entries()==3&&frame.toolbarRasters.entries()==0&&!frame.toolbarImageKey&&images(frame)==beforeFailure&&bound(frame)==beforeFailure&&!frame.appearanceReadSnapshot&&!frame.toolbarBuilding,"A failed reload retains active native images and leaves a retryable uncommitted cache");frame.applyAppearance();check(attempts==13&&frame.toolbarSources.entries()==12&&frame.toolbarRasters.entries()==1&&allPixels(images(frame))==savedPixels,"Retry reuses successful source slots and publishes all twelve icons and three states");
  frame.toolbarSourceObserver={};frame.toolbarRasterObserver={};check(manager.snapshot()["Settings"]==settings,"Image caching does not alter current application settings");cacheTimings["decoded-cache-bytes"]=frame.toolbarSources.bytes();cacheTimings["raster-cache-bytes"]=frame.toolbarRasters.bytes();cacheTimings["raster-entry-count"]=frame.toolbarRasters.entries();
